export function cleanAI(ai){if(!ai||ai.reviewed!==true||typeof ai.answer!=='string'||!ai.answer.trim()||ai.answer.length>3500||!['6-8','9-11','12-14'].includes(ai.ageBand))return null;const sources=(Array.isArray(ai.sources)?ai.sources:[]).filter(s=>{try{const u=new URL(s.url);return u.protocol==='https:'&&['zuno-kids.creativehub254.chatgpt.site','en.wikipedia.org'].includes(u.hostname)&&typeof s.title==='string'}catch{return false}}).slice(0,3).map(s=>({url:s.url,title:s.title.slice(0,180)}));return {answer:ai.answer,ageBand:ai.ageBand,sources,events:(Array.isArray(ai.events)?ai.events:[]).slice(0,5).map(e=>({label:String(e.label||'').slice(0,100)})),reviewed:ai.reviewed===true};}
export const HISTORY_KEY='zuno-chat-v1';
export const HISTORY_TTL=7*86400000;
export function questionGuard(question){
 const text=String(question||'').trim().slice(0,600);
 if(/[\w.+-]+@[\w.-]+\.[a-z]{2,}|(?:\+?\d[\d\s()-]{7,}\d)|\b(?:my (?:full name|name|address|school|password|phone)|i live at|i attend|my name'?s)\b/i.test(text))return {kind:'privacy',question:'[Private details left out]',message:'Let’s keep private details out of questions. Ask about an idea without sharing your name, school, address or phone number.'};
 if(/\b(?:suicide|self.harm|hurt myself|kill myself|kill someone|want to die|someone is hurt|abuse|porn|sexual content|nudes|how to (?:make|build) (?:a )?(?:bomb|weapon)|poison someone|take medicine|bleeding|cut myself|touching me|secret from|meet me)\b/i.test(text))return {kind:'support',question:'[Question kept private]',message:'Please talk to a trusted grown-up about this. If someone is hurt or you feel unsafe, tell a grown-up near you now. You can stop this activity whenever you want.'};
 return {kind:'question',question:text};
}
export function cleanHistory(raw,now=Date.now()){
 const threads=Array.isArray(raw?.threads)?raw.threads:[];
 return {active:null,threads:threads.filter(t=>typeof t.id==='string'&&Number.isFinite(t.updated)&&t.updated<=now&&t.updated>now-HISTORY_TTL).slice(0,12).map(t=>({id:t.id.slice(0,80),updated:t.updated,turns:(Array.isArray(t.turns)?t.turns:[]).slice(-24).filter(x=>typeof x.question==='string').map(x=>{const g=questionGuard(x.question);return {question:g.question,topic:g.kind==='question'&&/^[a-z0-9-]{1,80}$/.test(x.topic||'')?x.topic:null,kind:g.kind==='question'&&['question','privacy','support','missing'].includes(x.kind)?x.kind:g.kind,detail:['more','simple'].includes(x.detail)?x.detail:null,replyId:typeof x.replyId==='string'?x.replyId.slice(0,80):null,ai:g.kind==='question'?cleanAI(x.ai):null,at:Number.isFinite(x.at)?x.at:t.updated};})}))};
}
export function createChatStore({session,persistent,now=()=>Date.now(),id=()=>crypto.randomUUID()}={}){
 let remember=false,data={active:null,threads:[]},available=!!session&&!!persistent;
 try{remember=persistent?.getItem(HISTORY_KEY+'-remember')==='true';data=cleanHistory(JSON.parse((remember?persistent:session)?.getItem(HISTORY_KEY)||'{}'),now());data.active=data.threads[0]?.id||null;}catch{available=false;}
 const save=()=>{try{(remember?persistent:session)?.setItem(HISTORY_KEY,JSON.stringify(data));}catch{available=false;}};
 function current(){return data.threads.find(t=>t.id===data.active)||null;}
 function add(turn){let t=current();if(!t){t={id:id(),updated:now(),turns:[]};data.threads.unshift(t);data.active=t.id;}const g=questionGuard(turn.question);t.turns.push({...turn,question:g.question,topic:g.kind==='question'?turn.topic:null,kind:g.kind==='question'?turn.kind:g.kind,at:now()});t.turns=t.turns.slice(-24);t.updated=now();data.threads=[t,...data.threads.filter(x=>x.id!==t.id)].slice(0,12);save();return t;}
 save();
 return {get data(){return data},get available(){return available},get remember(){return remember},current,add,updateTurn(threadId,replyId,patch){const t=data.threads.find(t=>t.id===threadId),turn=t?.turns.find(x=>x.replyId===replyId);if(!turn)return false;Object.assign(turn,patch);if(turn.ai)turn.ai=cleanAI(turn.ai);save();return true},newChat(){data.active=null;save()},select(key){if(data.threads.some(t=>t.id===key)){data.active=key;save()}},remove(key){const removed=data.threads.find(t=>t.id===key);data.threads=data.threads.filter(t=>t.id!==key);if(data.active===key)data.active=null;save();return removed},restore(thread){if(thread&&!data.threads.some(t=>t.id===thread.id)){data.threads.unshift(thread);data.active=thread.id;save()}},setRemember(value){remember=!!value;try{persistent?.setItem(HISTORY_KEY+'-remember',String(remember));(remember?session:persistent)?.removeItem(HISTORY_KEY);}catch{available=false;}save()},clear(){data={active:null,threads:[]};save()}};
}
